import {positions,opening,purpose,disclosure,explanation,pathExplanation,initialShadow,shadowCaption,shadowHeading,waiting,pathNote,changeShadow,shadowAnnouncement,shadowNarration,shadowGeometry} from './shadow-theatre-core.mjs';
import {hearButton,stopSpeech,bindSpeech} from './play-media.mjs';
let session=null,owner=null,notebook=null;
export function resetShadow(){session=null;owner=null;notebook=null;}
function current(id,book){if(!session||owner!==id||notebook!==book){session=initialShadow();owner=id;notebook=book;}return session;}
const line=(x,y,xx,yy,cls)=>`<path class="${cls}" d="M${x} ${y}L${xx} ${yy}"/>`;
function arrow(x,y,xx,yy,frac){const a=Math.atan2(yy-y,xx-x),px=x+(xx-x)*frac,py=y+(yy-y)*frac;return `<path class="shadow-ray" data-ray-arrow d="M${px-7*Math.cos(a-.5)} ${py-7*Math.sin(a-.5)}L${px} ${py}L${px-7*Math.cos(a+.5)} ${py-7*Math.sin(a+.5)}"/>`;}
export function shadowPictures(s){
 const {d,width,height}=shadowGeometry(s),sx=280,sy=150,cx=40+d,top=sy-height/2,bottom=sy+height/2;
 let rays='';if(s.paths){const ends=s.present?[top,bottom]:[30,270];for(const ey of ends)rays+=line(40,sy,sx,ey,'shadow-ray')+arrow(40,sy,sx,ey,s.present?(d+(240-d)/2)/240:.55);rays+=line(40,sy,s.present?cx:sx,sy,'shadow-ray')+arrow(40,sy,s.present?cx:sx,sy,.5);if(s.present)rays+=line(cx-4,sy-4,cx+4,sy+4,'shadow-stop')+line(cx-4,sy+4,cx+4,sy-4,'shadow-stop');}
 return `<div class="shadow-pictures"><figure><h2>Side view</h2><svg viewBox="0 0 320 330" role="img" aria-label="Side view. ${shadowCaption(s)} Selected light paths ${s.paths?'shown':'hidden'}.${s.paths?' '+pathNote(s):''}"><text x="8" y="124">Lamp</text><text x="284" y="19" text-anchor="end">Screen</text>${line(sx,30,sx,270,'shadow-screen-edge')}${s.present?line(sx,top,sx,bottom,'shadow-screen-dark'):''}${line(40,292,280,292,'shadow-rail')}${positions.map(p=>line(40+p.d,287,40+p.d,297,'shadow-tick')).join('')}${rays}${s.present?line(cx,sy-30,cx,sy+30,'shadow-card'):''}<circle cx="40" cy="150" r="5" class="shadow-lamp"/></svg>${s.present?'<figcaption>Card seen edge-on</figcaption>':'<figcaption>Card removed</figcaption>'}</figure><figure><h2>Screen from the front</h2><svg viewBox="0 0 320 330" role="img" aria-label="Screen from the front. ${shadowCaption(s)}"><rect class="shadow-front-screen" x="40" y="30" width="240" height="240"/>${s.present?`<rect class="shadow-silhouette" x="${160-width/2}" y="${150-height/2}" width="${width}" height="${height}"/>`:''}</svg><figcaption>Shadow on this screen</figcaption><p>Card omitted here so the whole screen is visible.</p></figure></div>`;
}
const button=(action,label,disabled=false)=>`<button type="button" data-shadow-action="${action}"${disabled?' disabled':''}>${label}</button>`;
function view(s){return `<div class="shadow-current"><h2 id="shadow-current" tabindex="-1">${shadowHeading(s)}</h2><p>${shadowCaption(s)}</p>${!s.present?`<p>${waiting(s)}</p>`:''}</div><div class="shadow-controls"><div>${button('lamp','Move card toward lamp',!s.present||s.position==='lamp')}${button('screen','Move card toward screen',!s.present||s.position==='screen')}</div>${!s.present?'<p>Return the card before moving it.</p>':s.position!=='middle'?'<p>The card is already at this end.</p>':''}<div>${button('presence',s.present?'Remove card':'Return card')}<button type="button" data-shadow-action="paths" aria-pressed="${s.paths}">Light paths${s.paths?'<span aria-hidden="true">✓ Shown</span>':''}</button></div>${button('undo','Undo last change',!s.previous)}${!s.previous?'<p>No change to undo.</p>':''}</div><div class="shadow-key"><span aria-hidden="true"></span><p><strong>The same card</strong><br>Key, not to scale.${!s.present?'<br>Waiting outside the light picture.':''}</p></div>${shadowPictures(s)}<p class="shadow-pair-label">Two views of one lamp, one card and one screen.</p>${s.paths?`<div class="shadow-path-notes"><p>${pathExplanation}</p><p>${pathNote(s)}</p></div>`:''}${hearButton(shadowNarration(s),'Hear this picture')}`;}
export function shadowEntry(){return '<p class="shadow-entry"><a class="secondary" href="#loft/shadows">Shadow Theater: move a card, change its shadow</a></p>';}
export function shadowPage(id,book){const s=current(id,book);return `<section class="shadow-page"><header><a href="#loft"><span aria-hidden="true">←</span> Story Loft</a><h1 id="shadow-title" tabindex="-1">Shadow Theater</h1><p class="shadow-opening">${opening}</p><p>${purpose}</p></header><div data-shadow-view>${view(s)}</div><p id="shadow-status" role="status" aria-live="polite"></p><p>${disclosure}</p><details class="shadow-about"><summary>About this light picture</summary><p>${explanation}</p></details><footer><a href="#loft">Return to Story Loft</a><a href="#studio/bells">Visit Bell Studio</a></footer></section>`;}
export function bindShadow({explorerId,notebookState,focus}){
 const root=document.querySelector('.shadow-page');if(!root)return;
 const capturedOwner=explorerId(),capturedBook=notebookState(),capturedSession=current(capturedOwner,capturedBook);
 const live=()=>location.hash==='#loft/shadows'&&root.isConnected&&document.querySelector('.shadow-page')===root&&explorerId()===capturedOwner&&notebookState()===capturedBook&&owner===capturedOwner&&notebook===capturedBook&&session===capturedSession;
 root.querySelectorAll('[data-shadow-action]').forEach(b=>b.addEventListener('click',()=>{if(!live())return;const action=b.dataset.shadowAction,next=changeShadow(session,action);if(!next)return;stopSpeech();session=next;root.querySelector('[data-shadow-view]').innerHTML=view(session);bindShadow({explorerId,notebookState,focus});bindSpeech();root.querySelector('#shadow-status').textContent=shadowAnnouncement(session,action);const target=root.querySelector(`[data-shadow-action="${action}"]`);focus(action==='undo'||target.disabled?'#shadow-current':`[data-shadow-action="${action}"]`);}));
 root.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',e=>{if(!live()){e.preventDefault();e.stopImmediatePropagation();return;}b.dataset.speak=shadowNarration(session);},{capture:true}));
}
